import React, { useRef, useState, useEffect } from "react";

export default function VideoCarousel() {
  const videos = [
    "/assets/banner1.mp4",
    "/assets/banner2.mp4",
    "/assets/banner3.mp4",
    "/assets/banner4.mp4",
  ];
  const [index, setIndex] = useState(0);
  const [playing, setPlaying] = useState(false);
  const vRef = useRef(null);

  useEffect(() => {
    if (vRef.current) {
      playing ? vRef.current.play() : vRef.current.pause();
    }
  }, [index, playing]);

  const togglePlay = () => setPlaying((p) => !p);
  const next = () => {
    setIndex((i) => (i + 1) % videos.length);
    setPlaying(false);
  };
  const prev = () => {
    setIndex((i) => (i - 1 + videos.length) % videos.length);
    setPlaying(false);
  };

  return (
    <div style={{ position: "relative", width: "100%", overflow: "hidden" }}>
      <video
        key={videos[index]}
        ref={vRef}
        src={videos[index]}
        style={{ width: "100%", maxHeight: "500px", objectFit: "cover" }}
        controls={false}
        playsInline
        muted
        onClick={togglePlay}
      />

      {/* ⬅️ Prev button - circular white border */}
      <button
        onClick={prev}
        style={{
          position: "absolute",
          left: "20px",
          top: "50%",
          transform: "translateY(-50%)",
          fontSize: "2rem",
          color: "white",
          background: "transparent",
          border: "2px solid white",
          borderRadius: "50%",
          width: "45px",
          height: "45px",
          cursor: "pointer",
        }}
      >
        ⟨
      </button>

      {/* ➡️ Next button - circular white border */}
      <button
        onClick={next}
        style={{
          position: "absolute",
          right: "20px",
          top: "50%",
          transform: "translateY(-50%)",
          fontSize: "2rem",
          color: "white",
          background: "transparent",
          border: "2px solid white",
          borderRadius: "50%",
          width: "45px",
          height: "45px",
          cursor: "pointer",
        }}
      >
        ⟩
      </button>

      {/* 🎬 Middle play/pause icon — ONLY the symbol (no border/background) */}
      <button
        onClick={togglePlay}
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          fontSize: "3rem",
          color: "white",
          background: "none",
          border: "none",
          cursor: "pointer",
        }}
      >
        {playing ? "❚❚" : "►"}
      </button>
    </div>
  );
}
